syntax:
template <class InputIterator, class Distance>
void advance(InputIterator& i, Distance n);
// Implementation notes: This is the primary template declaration. Internally, it uses std::iterator_traits<InputIterator>::iterator_category to select a specialized overload. For example, if iterator_category is random_access_iterator_tag, it employs operator+= for O(1) advancement. Otherwise, it loops with operator++ for O(n) behavior. The compiler instantiates this per iterator type, optimizing based on the category at compile-time.

code_example:
#include <iostream>
#include <iterator>
#include <vector>
#include <list>
int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5};  // Uses random access iterator
    auto vecIt = vec.begin();
    std::advance(vecIt, 3);  // Advances by 3 positions
    std::cout << "Advanced vector iterator: " << *vecIt << std::endl;  // Outputs 4

    std::list<int> lst = {1, 2, 3, 4, 5};  // Uses bidirectional iterator
    auto lstIt = lst.begin();
    std::advance(lstIt, 3);  // Advances by 3 positions via increments
    std::cout << "Advanced list iterator: " << *lstIt << std::endl;  // Outputs 4
    return 0;
}
